import{_ as a}from"./chunks/file-menu.CeihNOyY.js";import{_ as s,o as n,c as e,a2 as o}from"./chunks/framework.Dx-TCpNt.js";const u=JSON.parse('{"title":"プロジェクトファイルと形式","description":"KomaYomi が保存するものはすべてプレーンファイルです。画像は raw/、注釈は data/、生成物は exports/ にあります。このページでは、その作業を別の場所へ移す3つの方法と、古いファイルを考古学にしないためのバージョン規則を説明します。","frontmatter":{"description":"KomaYomi が保存するものはすべてプレーンファイルです。画像は raw/、注釈は data/、生成物は exports/ にあります。このページでは、その作業を別の場所へ移す3つの方法と、古いファイルを考古学にしないためのバージョン規則を説明します。"},"headers":[],"relativePath":"ja/guide/project-files.md","filePath":"ja/guide/project-files.md","lastUpdated":1794768712000}'),i={name:"ja/guide/project-files.md"};function r(d,t,l,p,c,h){return n(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="プロジェクトファイルと形式" tabindex="-1">プロジェクトファイルと形式 <a class="header-anchor" href="#プロジェクトファイルと形式" aria-label="Permalink to &quot;プロジェクトファイルと形式&quot;">​</a></h1><p>KomaYomi が保存するものはすべてプレーンファイルです。画像は <code>raw/</code>、注釈は <code>data/</code>、生成物は <code>exports/</code> にあります。このページでは、その作業を別の場所へ移す3つの方法と、古いファイルを考古学にしないためのバージョン規則を説明します。</p><h2 id="解決する課題" tabindex="-1">解決する課題 <a class="header-anchor" href="#解決する課題" aria-label="Permalink to &quot;解決する課題&quot;">​</a></h2><p>注釈はもっとも高価な部分です。コマの修正、位置合わせ、ノートに何時間もかかります。マシンの変更、ディスク障害、学習パートナーとの共有、将来のアプリバージョンを越えて残る必要があります。データベースのバックアップは不透明ですが、これらの形式はプレーンな ZIP と JSON で、普通のツールで検査できます。</p><h2 id="_3つの可搬レイヤー" tabindex="-1">3つの可搬レイヤー <a class="header-anchor" href="#_3つの可搬レイヤー" aria-label="Permalink to &quot;3つの可搬レイヤー&quot;">​</a></h2><table tabindex="0"><thead><tr><th>レイヤー</th><th>ファイル</th><th>内容</th><th>使う場面</th></tr></thead><tbody><tr><td><strong>プロジェクトパッケージ</strong></td><td><code>.mnproj</code></td><td>画像（パッケージモード）、ページ JSON、テンプレート、プリセット、言語マッピング</td><td>別のマシンへ移す、または完成した巻をアーカイブするとき。</td></tr><tr><td><strong>交換ファイル</strong></td><td><code>.mntpl</code>、<code>.mnexp</code>、<code>.mnpage.json</code></td><td>1つのレイアウト、1つのエクスポートスタイル、1つのページ</td><td>再利用できるレイアウトや、注釈済みの1ページを共有するとき。</td></tr><tr><td><strong>バックアップ ZIP</strong></td><td><code>.zip</code></td><td><code>data/</code> フォルダ全体</td><td>操作ミスの後に復元する、または定期的な安全コピーを保つとき。</td></tr></tbody></table><figure class="shot"><img src="'+a+`" alt="ファイルメニュー。ライブラリを開く、プロジェクトファイル、最近の巻、保存、読み込み、復元"><figcaption>ファイルメニューはサイドバーと同じ操作をまとめています。現在のページを保存、プロジェクトとして保存、プロジェクトやページの読み込み、バックアップからの復元。</figcaption></figure><h2 id="プロジェクトパッケージ-mnproj" tabindex="-1">プロジェクトパッケージ（<code>.mnproj</code>） <a class="header-anchor" href="#プロジェクトパッケージ-mnproj" aria-label="Permalink to &quot;プロジェクトパッケージ（\`.mnproj\`）&quot;">​</a></h2><p><code>.mnproj</code> はテキストのマニフェストを含む ZIP です。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>manifest.json</span></span>
<span class="line"><span>pages/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>history/&lt;volume&gt;/&lt;chapter&gt;/&lt;index&gt;.json</span></span>
<span class="line"><span>templates/...</span></span>
<span class="line"><span>presets/...</span></span>
<span class="line"><span>config/library.json          (optional)</span></span>
<span class="line"><span>assets/&lt;sha1&gt;.&lt;ext&gt;          (packaged mode only)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>ページ版履歴もプロジェクトに含まれるため、開き直したあとも<a href="/KomaYomi-docs/ja/guide/panels#ページ版履歴">コマ分割ワークベンチ</a>で説明した記録を確認できます。</p><h3 id="参照モードとパッケージモード" tabindex="-1">参照モードとパッケージモード <a class="header-anchor" href="#参照モードとパッケージモード" aria-label="Permalink to &quot;参照モードとパッケージモード&quot;">​</a></h3><table tabindex="0"><thead><tr><th>モード</th><th>画像</th><th>サイズ</th><th>可搬性</th></tr></thead><tbody><tr><td><strong>参照</strong></td><td>マニフェストにはパスと SHA-1 ハッシュのみ。</td><td>小さい。</td><td>元の画像フォルダが必要。ハッシュまたはファイル名による再リンクに対応。</td></tr><tr><td><strong>パッケージ</strong></td><td><code>assets/&lt;sha1&gt;.&lt;ext&gt;</code> に重複排除して格納。</td><td>大きい。</td><td>自己完結。インポートすると画像が <code>raw/</code> に書き込まれます。</td></tr></tbody></table><h3 id="エクスポート" tabindex="-1">エクスポート <a class="header-anchor" href="#エクスポート" aria-label="Permalink to &quot;エクスポート&quot;">​</a></h3><ol><li>サイドバーの <strong>プロジェクトファイル…</strong> を開くか、<strong>ファイル → プロジェクトとして保存…</strong> を選びます。</li><li>モード、プロジェクト名、任意のメモを入力します。</li><li><strong>.mnproj を生成してダウンロード</strong> をクリックします。</li></ol><p>マニフェストにはアプリのバージョン、作成日時、言語マッピング、巻 / 話 / ページと画像ハッシュの一覧、ノートと注釈の件数が記録されます。</p><h3 id="インポート" tabindex="-1">インポート <a class="header-anchor" href="#インポート" aria-label="Permalink to &quot;インポート&quot;">​</a></h3><ol><li><strong>プロジェクトファイルを選択…</strong> をクリックします。書き込む前に、巻、話、ページ、ノート、注釈、画像、テンプレートの概要が表示されます。</li><li>競合ポリシーを選びます。<strong>上書き</strong>、<strong>結合</strong>、<strong>スキップ</strong> です。 <ul><li><strong>結合</strong> は、取り込むページにコマや注釈がない場合に既存のものを保持し、ノートは id で統合して既存のノートを削除しません。</li></ul></li><li>参照モードのプロジェクトで画像が不足している場合は、任意で元画像のある <strong>再リンク先フォルダ</strong> を選べます。</li><li><strong>インポートする</strong> をクリックします。</li></ol><p>安全のための動作:</p><ul><li>インポートの前に、現在の <code>data/</code> が <code>exports/</code> にスナップショットされます。</li><li>元のプロジェクトファイルは <code>data/backups/projects/</code> にバックアップされます。</li><li>不足している画像はインポート後に報告されます。再リンク先フォルダに置き、<strong>結合</strong> でもう一度インポートすれば復元できます。</li></ul><h2 id="交換ファイル" tabindex="-1">交換ファイル <a class="header-anchor" href="#交換ファイル" aria-label="Permalink to &quot;交換ファイル&quot;">​</a></h2><p><strong>交換ファイル…</strong> は、ライブラリ全体に触れずに3つの小さな形式を扱います。</p><h3 id="mntpl-—-レイアウトテンプレート" tabindex="-1"><code>.mntpl</code> — レイアウトテンプレート <a class="header-anchor" href="#mntpl-—-レイアウトテンプレート" aria-label="Permalink to &quot;\`.mntpl\` — レイアウトテンプレート&quot;">​</a></h3><p>エクスポート時には巻 / 話 / ページの紐付けが外れるため、テンプレートは別の漫画にインポートし、現在の巻、話、ページに紐付け直せます。インポートダイアログでは紐付けを指定でき、その場で適用することもできます。既存のページは先に保存されます。</p><h3 id="mnexp-—-エクスポートテンプレート" tabindex="-1"><code>.mnexp</code> — エクスポートテンプレート <a class="header-anchor" href="#mnexp-—-エクスポートテンプレート" aria-label="Permalink to &quot;\`.mnexp\` — エクスポートテンプレート&quot;">​</a></h3><p>HTML、Word、印刷ドキュメントのレイアウトとスタイル設定を保存します。今エクスポートして、後でインポートできます。テンプレートの保存先は <code>data/templates/export.json</code> です。</p><h3 id="mnpage-json-—-1ページ" tabindex="-1"><code>.mnpage.json</code> — 1ページ <a class="header-anchor" href="#mnpage-json-—-1ページ" aria-label="Permalink to &quot;\`.mnpage.json\` — 1ページ&quot;">​</a></h3><p>コマ、ノート、タグ、グループ、注釈、位置合わせオフセットを含む、読めるページドキュメントです。スキーマのエンベロープがない古いページ JSON もインポートでき、移行されます。</p><ul><li><strong>現在のページを書き出す</strong> は現在のページを書き出します。</li><li><strong>ページ JSON を選択…</strong> の後に <strong>現在のページを上書き</strong> で、選択中のページのコマ、ノート、注釈を置き換えます。</li><li>検証に失敗すると正確なフィールドパスが報告され、中途半端なデータは書き込まれません。</li><li>元のファイルは <code>data/backups/exchange/</code> にバックアップされます。</li></ul><div class="warning custom-block"><p class="custom-block-title">未保存の変更</p><p>ページに未保存の編集がある場合、交換ファイルのエクスポートには含まれず、ページのインポートで上書きされる可能性があります。先に保存してください。ダイアログは警告しますが、うっかり通り過ぎやすいです。</p></div><h2 id="形式のバージョン" tabindex="-1">形式のバージョン <a class="header-anchor" href="#形式のバージョン" aria-label="Permalink to &quot;形式のバージョン&quot;">​</a></h2><p>すべての交換形式はスキーマのエンベロープを持ちます。</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://manga-memo.dev/schemas/page.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;schemaVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;appVersion&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;0.1.0&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;kind&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;page&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><table tabindex="0"><thead><tr><th>種類</th><th>ファイル</th><th>現在のバージョン</th></tr></thead><tbody><tr><td><code>mnproj</code></td><td><code>.mnproj</code> マニフェスト</td><td><strong>1</strong></td></tr><tr><td><code>mntpl</code></td><td>レイアウトテンプレート</td><td><strong>1</strong></td></tr><tr><td><code>mnexp</code></td><td>エクスポートテンプレート</td><td><strong>1</strong></td></tr><tr><td><code>page</code></td><td>ページドキュメント</td><td><strong>1</strong></td></tr><tr><td><code>mntp</code></td><td>コマテンプレート（保存用）</td><td><strong>1</strong></td></tr><tr><td><code>mnalign</code></td><td>位置合わせプリセット（保存用）</td><td><strong>1</strong></td></tr><tr><td><code>mnlayout</code></td><td>宣言的レイアウト（保存用）</td><td><strong>1</strong></td></tr><tr><td><code>mnconfig</code></td><td>ライブラリ設定（保存用）</td><td><strong>1</strong></td></tr><tr><td><code>mnstorage</code></td><td>ストレージ設定（保存用）</td><td><strong>1</strong></td></tr></tbody></table><p>バージョンの規則:</p><ul><li>アプリが対応するより<strong>高い</strong>バージョンを宣言するファイルは、明確なメッセージとともに拒否されます。先にアプリをアップグレードしてください。アプリが将来の形式を推測することはありません。</li><li>バージョンがない場合は <strong>v0</strong> として扱われ、インポート時に移行されます。初期の実験的なマニフェスト（トップレベルの <code>images</code>、フラットな <code>langDirs</code> マップ）は現在の形に変換されます。</li><li>省略された任意フィールドは既定値で補われ、無効な画像はインポート全体を中断せずに破棄されます。</li><li>読み込み時にページ JSON は<strong>正規化</strong>されます。矩形は範囲内に丸められ、ぶら下がったグループ参照は削除され、欠けた id は生成され、不明なフィールドは破棄されます。</li><li>解析できないページ JSON は存在しないものとして扱われ、アプリが再検出して作り直します。</li></ul><h2 id="バックアップ-zip" tabindex="-1">バックアップ ZIP <a class="header-anchor" href="#バックアップ-zip" aria-label="Permalink to &quot;バックアップ ZIP&quot;">​</a></h2><p>バックアップは、各エントリの先頭に <code>data/</code> が付く ZIP です。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/pages/...</span></span>
<span class="line"><span>data/templates/...</span></span>
<span class="line"><span>data/presets/...</span></span>
<span class="line"><span>data/layouts/...</span></span>
<span class="line"><span>data/library.json</span></span>
<span class="line"><span>data/.backup-meta.json</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>除外されるもの：<code>data/cache/</code>（サムネイルとリモートキャッシュ）、<code>.tmp</code> ファイル、ログ。復元は同名ファイルを上書きし、バックアップにないページは残し、最初にスナップショットを書き出します。</p><h2 id="未実装の機能" tabindex="-1">未実装の機能 <a class="header-anchor" href="#未実装の機能" aria-label="Permalink to &quot;未実装の機能&quot;">​</a></h2><ul><li><strong>語彙リストのエクスポート。</strong> PDF と Word は、エクスポートダイアログの <strong>PDF（印刷）</strong> と <strong>Word 文書</strong> で対応します。</li><li><strong>定期的なバックアップ。</strong> バックアップとバックアップ先へのアップロードは手動で開始します。</li><li><strong>アプリ内の画像変換と一括リネーム。</strong> 取り込み前にファイルを整えてください。<a href="/KomaYomi-docs/ja/guide/preprocess">画像の前処理と名前変更</a>を参照してください。</li></ul><h2 id="よくある落とし穴" tabindex="-1">よくある落とし穴 <a class="header-anchor" href="#よくある落とし穴" aria-label="Permalink to &quot;よくある落とし穴&quot;">​</a></h2><ul><li><strong>参照モードのプロジェクトで画像が不足する。</strong> マニフェストにはハッシュとパスのみが保存されます。再リンク先フォルダを使うか、次回はパッケージモードでエクスポートしてください。</li><li><strong>「スキーマのバージョンが新しすぎます。」</strong> ファイルはより新しいビルドのものです。アプリを更新してください。<code>schemaVersion</code> を手で編集しないでください。</li><li><strong>インポートで新しいノートが上書きされた。</strong> <strong>上書き</strong> は仕様上破壊的です。迷ったら <strong>結合</strong> を使ってください。スナップショットは書き出されていますが、復元すると現在のデータが置き換わります。</li><li><strong>レイアウトテンプレートが表示されない。</strong> 現在の話 / 巻のフィルターに紐付いています。インポートダイアログで紐付けを確認してください。</li><li><strong><code>.mnpage.json</code> をインポートしても画像がない。</strong> ページデータに画像は含まれません。画像は <code>raw/</code> またはパッケージ化したプロジェクトから来ます。</li></ul><figure class="shot"><div class="shot-missing"><strong>スクリーンショット未掲載：プロジェクトのインポート概要</strong> 一覧の件数、競合ポリシー、再リンク先のフィールドを表示したインポートダイアログのスクリーンショットを、ここに追加する予定です。 </div><figcaption>掲載予定：プロジェクトのインポート概要。</figcaption></figure><h2 id="スクリーンショット未掲載" tabindex="-1">スクリーンショット未掲載 <a class="header-anchor" href="#スクリーンショット未掲載" aria-label="Permalink to &quot;スクリーンショット未掲載&quot;">​</a></h2><table tabindex="0"><thead><tr><th>図</th><th>必要な箇所</th></tr></thead><tbody><tr><td>プロジェクトのエクスポートフォーム</td><td>モード、名前、メモ</td></tr><tr><td>プロジェクトのインポート概要</td><td>件数、競合、再リンク</td></tr><tr><td>交換ファイルのダイアログ</td><td>3つのファイル形式</td></tr></tbody></table><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/KomaYomi-docs/ja/data-format">データ形式</a> — JSON フィールドの完全なリファレンス。</li><li><a href="/KomaYomi-docs/ja/guide/export">エクスポート</a> — HTML、Word、PDF、PNG の出力。</li><li><a href="/KomaYomi-docs/ja/guide/remote">リモート保存とバックアップ</a> — バックアップ先。</li></ul>`,49)])])}const b=s(i,[["render",r]]);export{u as __pageData,b as default};
